from __future__ import annotations

from playwright.sync_api import Locator, Page

from components.catalog_search_form import CatalogSearchForm
from pages.base_page import BasePage

TRACEABILITY = ('pom_page_catalog', 'page_catalog', 'method_open_catalog', 'method_read_results', 'pom_component_search_form')


class CatalogPage(BasePage):
    """Application-facing actions and state for the mapped page."""

    def __init__(self, page: Page, base_url: str = "") -> None:
        super().__init__(page, base_url=base_url)
        self.search_form = CatalogSearchForm(page)

    @property
    def results_heading(self) -> Locator:
        """Return the observed locator loc_results_heading_role."""
        return self.page.get_by_role('heading', name='Search results')

    @property
    def results_list(self) -> Locator:
        """Return the observed locator loc_results_list_test_id."""
        return self.page.get_by_test_id('catalog-results')

    def open_catalog(self) -> None:
        """Open the catalog page through the framework navigation boundary."""
        self.open()

    def read_results(self) -> str:
        """Expose the visible results state for test-level verification."""
        return self.results_list.inner_text()

