from __future__ import annotations

from playwright.sync_api import Locator, Page

from components.base_component import BaseComponent

TRACEABILITY = ('pom_component_search_form', 'cmp_search_form', 'method_enter_query', 'method_submit_search')


class CatalogSearchForm(BaseComponent):
    """Application-facing actions for the mapped UI component."""

    def __init__(self, page: Page) -> None:
        super().__init__(page)

    @property
    def search_input(self) -> Locator:
        """Return the observed locator loc_search_input_label."""
        return self.page.get_by_label('Search catalog')

    @property
    def search_submit(self) -> Locator:
        """Return the observed locator loc_search_submit_role."""
        return self.page.get_by_role('button', name='Search')

    def enter_query(self, value: str) -> None:
        """Fill the observed search input with symbolic test data."""
        self.search_input.fill(value)

    def submit_search(self) -> None:
        """Submit the search through the observed Search button."""
        self.search_submit.click()
